diff --git a/test.js b/test.js
index e303a46..38dd0d4 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,45 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue keeps the active promise and discards every queued function by default', async t => {
+	const limit = pLimit(1);
+	const started = [];
+
+	const activePromise = limit(async () => {
+		started.push('active');
+		await delay(50);
+		return 'active result';
+	});
+
+	const queuedPromises = ['one', 'two', 'three'].map(name => limit(async () => {
+		started.push(name);
+		return name;
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	// Public API is unchanged: `clearQueue()` takes no arguments and returns nothing.
+	t.is(limit.clearQueue(), undefined);
+
+	// The running function is untouched, only the queue is emptied.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+	t.is(await activePromise, 'active result');
+
+	// Without `rejectOnClear`, the discarded functions never run and never settle.
+	const pending = Symbol('pending');
+	t.is(await Promise.race([
+		Promise.allSettled(queuedPromises),
+		delay(100, pending),
+	]), pending);
+	t.deepEqual(started, ['active']);
+
+	// The limit remains usable afterwards.
+	t.is(await limit(() => 'after clear'), 'after clear');
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;
